import type { TableName } from '../db'
import type { UxListMenuConfig } from './UxListMenuConfig'

export type Workspace = Now.Internal.WithID<
    {
        /** The display name of the workspace */
        title: string
        /** The URL path or route associated with this workspace */
        path: string
        /** The default landing path for the workspace */
        landingPath?: string
        /** The order the workspace is displayed in the unified nav */
        order?: number
        /** Whether this workspace is currently active */
        active?: boolean
        /** The List Config for this workspace */
        listConfig?: UxListMenuConfig | string
        /** The tables associated with this workspace */
        tables?: TableName[]
        /** When records that are not tracked by the plugin are modified on instance, they are tracked here */
        defaultRecordOverrides?: {
            [record: string]: { [key: string]: unknown }
        }

        // additionalRecords?: { id: string; table: string; data: { [key: string]: string } }[]
    } & Now.Internal.Meta
>

/**
 * Creates a workspace configuration
 *
 * @param config - an object containing the following properties:
 *   * **title** - The display name of the workspace
 *   * **path** - The URL path or route associated with this workspace
 *   * **landingPath** - (optional) The default landing path for the workspace
 *   * **order** - (optional) The order the workspace is displayed in the unified nav
 *   * **active** - (optional) Whether this workspace is currently active
 *   * **listConfig** - (optional) The List Config for this workspace
 *   * **tables** - (optional) The tables associated with this workspace
 *   * **defaultRecordOverrides** - (optional) When records that are not tracked by the plugin are modified on instance, they are tracked here
 */
export function Workspace(config: Workspace) {
    return config
}
